int ex_name(const char*a,const char*b){const char*p=strrchr(a,':');return !strcasecmp(p?p+1:a,b);}
static unsigned utf8(char*p,unsigned cp){if(cp<128){p[0]=(char)cp;return 1;}if(cp<0x800){p[0]=0xc0|(cp>>6);p[1]=0x80|(cp&63);return 2;}if(cp<0x10000){p[0]=0xe0|(cp>>12);p[1]=0x80|((cp>>6)&63);p[2]=0x80|(cp&63);return 3;}p[0]=0xf0|(cp>>18);p[1]=0x80|((cp>>12)&63);p[2]=0x80|((cp>>6)&63);p[3]=0x80|(cp&63);return 4;}
unsigned ex_decode(const char*s,unsigned n,char*out,unsigned cap){if(!cap)return 0;unsigned used=0;for(unsigned i=0;i<n;){if(s[i]!='&'){if(used+1>=cap)break;out[used++]=s[i++];continue;}unsigned end=i+1;while(end<n&&end-i<50&&s[end]!=';')end++;if(end>=n||s[end]!=';'){if(used+1>=cap)break;out[used++]=s[i++];continue;}char key[52],numeric[5];unsigned len=end-i-1;memcpy(key,s+i+1,len);key[len]=0;const char*value=0;if(key[0]=='#'){char*tail;unsigned long cp=strtoul(key+(key[1]=='x'||key[1]=='X'?2:1),&tail,key[1]=='x'||key[1]=='X'?16:10);if(*tail||!cp||cp>0x10ffff||(cp>=0xd800&&cp<=0xdfff))cp=0xfffd;numeric[utf8(numeric,(unsigned)cp)]=0;value=numeric;}else{unsigned lo=0,hi=sizeof ep_entities/sizeof*ep_entities;while(lo<hi){unsigned mid=lo+(hi-lo)/2;if(strcmp(ep_entities[mid].name,key)<0)lo=mid+1;else hi=mid;}if(lo<sizeof ep_entities/sizeof*ep_entities&&!strcmp(ep_entities[lo].name,key))value=ep_entities[lo].value;}if(!value)value="\xef\xbf\xbd";len=(unsigned)strlen(value);if(used+len>=cap)break;memcpy(out+used,value,len);used+=len;i=end+1;}out[used]=0;return used;}
int ex_attribute(const struct ex_tag*t,const char*name,char*out,unsigned cap){for(unsigned i=0;i<t->count;i++)if(ex_name(t->attrs[i].key,name)){if(t->attrs[i].length+1>cap)return 0;ex_decode(t->attrs[i].value,t->attrs[i].length,out,cap);return 1;}if(cap)out[0]=0;return 0;}
int ex_next(struct ex_parser*p,struct ex_tag*t){memset(t,0,sizeof(*t));while(p->pos<p->size){unsigned a=p->pos;if(p->data[a]!='<'){unsigned end=a;while(end<p->size&&p->data[end]!='<')end++;t->kind=EX_TEXT;t->text=p->data+a;t->length=end-a;p->pos=end;return 1;}if(a+4<=p->size&&!memcmp(p->data+a,"<!--",4)){const char*z=strstr(p->data+a+4,"-->");if(!z){p->error=1;return 0;}p->pos=(unsigned)(z-p->data)+3;continue;}if(a+9<=p->size&&!memcmp(p->data+a,"<![CDATA[",9)){const char*z=strstr(p->data+a+9,"]]>");if(!z){p->error=1;return 0;}t->kind=EX_TEXT;t->text=p->data+a+9;t->length=(unsigned)(z-(p->data+a+9));p->pos=(unsigned)(z-p->data)+3;return 1;}
 if(a+2<p->size&&(p->data[a+1]=='!'||p->data[a+1]=='?')){unsigned j=a+2,brackets=0;char quote=0;for(;j<p->size;j++){char c=p->data[j];if(quote){if(c==quote)quote=0;}else if(c=='\''||c=='"')quote=c;else if(c=='[')brackets++;else if(c==']'&&brackets)brackets--;else if(c=='>'&&!brackets)break;}if(j==p->size){p->error=1;return 0;}p->pos=j+1;continue;}
 unsigned i=a+1;t->kind=EX_START;if(p->data[i]=='/'){t->kind=EX_END;i++;}while(i<p->size&&isspace((unsigned char)p->data[i]))i++;unsigned first=i;while(i<p->size&&!isspace((unsigned char)p->data[i])&&p->data[i]!='>'&&p->data[i]!='/')i++;unsigned len=i-first;if(!len||len>=sizeof t->name){p->error=1;return 0;}memcpy(t->name,p->data+first,len);t->name[len]=0;
 while(i<p->size){while(i<p->size&&isspace((unsigned char)p->data[i]))i++;if(i==p->size)break;if(p->data[i]=='>'){p->pos=i+1;return 1;}if(p->data[i]=='/'&&i+1<p->size&&p->data[i+1]=='>'){t->self=1;p->pos=i+2;return 1;}if(t->kind==EX_END||t->count==32){p->error=1;return 0;}first=i;while(i<p->size&&!isspace((unsigned char)p->data[i])&&p->data[i]!='='&&p->data[i]!='>')i++;len=i-first;if(!len||len>=64){p->error=1;return 0;}struct ex_attr*r=t->attrs+t->count;memcpy(r->key,p->data+first,len);r->key[len]=0;while(i<p->size&&isspace((unsigned char)p->data[i]))i++;if(i==p->size||p->data[i++]!='='){p->error=1;return 0;}while(i<p->size&&isspace((unsigned char)p->data[i]))i++;if(i==p->size||(p->data[i]!='\''&&p->data[i]!='"')){p->error=1;return 0;}char q=p->data[i++];first=i;while(i<p->size&&p->data[i]!=q)i++;if(i==p->size){p->error=1;return 0;}r->value=p->data+first;r->length=i-first;t->count++;i++;}
 p->error=1;return 0;}return 0;}
